def remove_account(request):
    # CSRF protection: Validate CSRF token in headers
    if 'headers' not in request or 'X-CSRF-Token' not in request['headers']:
        return False
    if request['headers']['X-CSRF-Token'] != EXPECTED_CSRF_TOKEN:
        return False

    # Input validation: Check for required user_id in request body
    if 'body' not in request or 'user_id' not in request['body']:
        return False
    user_id = request['body']['user_id']

    # Validate user existence in database
    if user_id not in database['users']:
        return False

    # Delete user from database
    del database['users'][user_id]
    return True

import json

def discard_user(req_info):
    # CSRF protection: Validate expected CSRF token in headers
    csrf_token = req_info['headers'].get('X-CSRF-Token', '')
    if csrf_token != EXPECTED_CSRF_TOKEN:
        return False

    # Input validation: Parse and validate user_id from JSON body
    try:
        body = json.loads(req_info['body'])
        user_id = body.get('user_id')
    except json.JSONDecodeError:
        return False

    if not isinstance(user_id, str):
        return False

    # Data minimization: Check user existence in database
    if user_id not in database['users']:
        return False

    # Safe deletion from database
    try:
        del database['users'][user_id]
        return True
    except KeyError:
        return False

