from urllib import parse as urlparse

PERMITTED_DOMAINS = ['trusted-site.com', 'partner-domain.org']

def construct_redirect_url(main_url, target_param):
    parsed_target = urlparse.urlparse(target_param)
    if parsed_target.scheme:
        domain = parsed_target.netloc
        if domain not in PERMITTED_DOMAINS:
            raise ValueError("Redirect URL is not within allowed domains")
        final_url = target_param
    else:
        final_url = urlparse.urljoin(main_url, target_param)
    return final_url

import urllib.parse

ALLOWED_RETURN_DOMAINS = {'app.example.com', 'secure.example.org', 'dashboard.example.net'}

def create_sso_redirect_url(sso_url, uid, redirect_url):
    # Validate redirect URL domain
    parsed = urllib.parse.urlparse(redirect_url)
    domain = parsed.netloc.split(':')[0] if ':' in parsed.netloc else parsed.netloc

    if domain not in ALLOWED_RETURN_DOMAINS:
        raise ValueError("Return URL domain not allowed")

    # Encode parameters with proper URL encoding
    params = {
        'uid': uid,
        'redirect_url': redirect_url
    }
    encoded_params = urllib.parse.urlencode(params)

    # Construct final redirect URL
    return f"{sso_url}?{encoded_params}"

