import urllib.parse

ALLOWED_CALLBACK_DOMAINS = {'auth.myapp.com', 'login.myapp.org', 'oauth.myapp.net'}

def assemble_oauth_callback_url(root_url, path_for_callback, session_token):
    # Combine base URL and callback path using urljoin for proper URL construction
    base_url = urllib.parse.urljoin(root_url, path_for_callback)
    # Encode state parameter to prevent query injection
    query_params = {'state': session_token}
    full_url = f"{base_url}?{urllib.parse.urlencode(query_params)}"
    # Parse URL to extract hostname for domain validation
    parsed = urllib.parse.urlparse(full_url)
    if not parsed.hostname:
        raise ValueError("Invalid URL: no hostname")
    if parsed.hostname not in ALLOWED_CALLBACK_DOMAINS:
        raise ValueError("Callback URL domain not allowed")
    return full_url

import urllib.parse

ALLOWED_CALLBACK_DOMAINS = {'auth.myapp.com', 'login.myapp.org', 'oauth.myapp.net'}

def generate_oauth_url(host_url, path_callback, session_id):
    # Canonicalize domain by removing port numbers
    parsed_host = urllib.parse.urlparse(host_url)
    domain = parsed_host.netloc.split(':')[0] if ':' in parsed_host.netloc else parsed_host.netloc

    # Allowlisting: Check if domain is in allowed set
    if domain not in ALLOWED_CALLBACK_DOMAINS:
        raise ValueError("Callback URL domain not allowed")

    # Construct base URL with path_callback using urljoin
    base_url = urllib.parse.urljoin(host_url, path_callback)

    # Encode state parameter with query string
    query_params = {'state': session_id}
    parsed_base = urllib.parse.urlparse(base_url)
    final_query = parsed_base.query
    if final_query:
        final_query += '&' + urllib.parse.urlencode(query_params)
    else:
        final_query = urllib.parse.urlencode(query_params)

    return parsed_base._replace(query=final_query).geturl()

import urllib.parse

APPROVED_API_DOMAINS = {'api.myservice.com', 'api-test.myservice.com', 'api-staging.myservice.com'}
ALLOWED_ENDPOINTS = ['/v1/data', '/v1/user', '/v2/analytics', '/health']

def construct_api_redirect(base_api_url, api_endpoint, query_options=None):
    # Combine base URL and endpoint with proper URL normalization
    base_url = urllib.parse.urljoin(base_api_url, api_endpoint)

    # Validate domain using allowlisting
    parsed_base = urllib.parse.urlparse(base_url)
    if parsed_base.netloc not in APPROVED_API_DOMAINS:
        raise ValueError("Domain not allowed")

    # Validate endpoint using allowlisting
    if api_endpoint not in ALLOWED_ENDPOINTS:
        raise ValueError("Endpoint not allowed")

    # Encode query parameters safely
    if query_options:
        query_params = urllib.parse.urlencode(query_options)
        full_url = f"{base_url}?{query_params}"
    else:
        full_url = base_url

    return full_url

import urllib.parse

ALLOWED_CDN_DOMAINS = {'cdn.example.com', 'assets.example.net', 'static.example.org'}

def construct_external_resource_url(cdn_base_url, resource_id, resource_type):
    parsed = urllib.parse.urlparse(cdn_base_url)
    domain = parsed.netloc
    if domain not in ALLOWED_CDN_DOMAINS:
        raise ValueError("CDN base URL domain is not allowed")
    constructed_url = urllib.parse.urljoin(cdn_base_url, f"{resource_type}/{resource_id}")
    return constructed_url

import re
from urllib import parse as urlparse

SCHEME_RE = re.compile(r"^[a-z]+:", re.I)

def make_location_absolute(value, host_name, url_scheme):
    if SCHEME_RE.match(value):
        return value
    base_url = f"{url_scheme}://{host_name}"
    return urlparse.urljoin(base_url, value)

