    if active_user_id not in USERS:
        return 'Unauthorized'

    # Allowlisting: Validate profile_id exists in USER_PROFILES
    if profile_id not in USER_PROFILES:
        return 'Unauthorized'

    # RBAC: Check if active user is admin
    user = USERS[active_user_id]
    if user['role'] == 'admin':
        return USER_PROFILES[profile_id]

    # RBAC: Non-admin users can only access their own profile
    if profile_id == active_user_id:
        return USER_PROFILES[profile_id]

    return 'Unauthorized'

